border-radius:20px;background:#121e27;box-shadow:inset 0 2px 4px rgba(0,0,0,.3);overflow:hidden}.battery-fill{position:relative;height:100%;width:64%;border-radius:inherit;background:linear-gradient(90deg,#82c5ae 0%,#b4d79a 62%,#f4d18c 100%);box-shadow:0 0 13px rgba(163,213,167,.35);transition:width .32s ease,filter .3s}.battery-fill.low{background:linear-gradient(90deg,#d19c73,#edca8d)}.fill-shimmer{position:absolute;inset:0;background:linear-gradient(100deg,transparent 35%,rgba(255,255,255,.26) 49%,transparent 63%);animation:shimmer 4s ease-in-out infinite}.battery-tick{position:absolute;top:0;height:100%;width:1px;background:rgba(21,35,39,.33)}.tick-25{left:25%}.tick-50{left:50%}.tick-75{left:75%}.battery-scale{display:flex;justify-content:space-between;font-size:9px;color:#768b8b}.charge-button{width:100%;display:flex;align-items:center;justify-content:center;gap:10px;margin-top:19px;padding:14px 15px;border:1px solid rgba(249,215,155,.33);border-radius:9px;background:linear-gradient(105deg,#d4ad75,#e9c78e);color:#253535;font-size:12px;font-weight:700;letter-spacing:.015em;cursor:pointer;box-shadow:0 6px 20px rgba(203,161,96,.12),inset 0 1px rgba(255,255,255,.45);transition:transform .16s,box-shadow .16s,filter .16s}.charge-button:hover{filter:brightness(1.07);box-shadow:0 7px 25px rgba(203,161,96,.24),inset 0 1px rgba(255,255,255,.5);transform:translateY(-1px)}.charge-button:active{transform:translateY(1px) scale(.99)}.charge-button:focus-visible,.sound-toggle:focus-visible,.reset-button:focus-visible{outline:2px solid #fff0c9;outline-offset:3px}.button-icon{font-size:15px}.button-plus{margin-left:auto;border-radius:12px;padding:4px 8px;background:rgba(37,53,53,.13);font-size:10px}.drain-note{display:flex;justify-content:center;align-items:center;gap:5px;margin-top:13px;color:#98aaa9;font-size:9px}.drain-icon{color:#c7ab7b;font-size:12px}.drain-rate{color:#829391}.charge-feedback{height:14px;text-align:center;margin-top:3px;font-size:10px;color:#f2d79c;opacity:0;transition:opacity .2s}.charge-feedback.show{opacity:1}.session-stats{display:flex;align-items:center;justify-content:center;gap:10px;margin-top:18px;color:#c8d0c8;font-size:11px}.session-stats>div{display:flex;align-items:center;gap:5px}.stat-icon{color:#e8ca91;font-size:13px}.stat-moon{font-size:14px}.stat-label{color:#8f9f9e;font-size:10px;margin-left:1px}.stat-divider{height:13px;width:1px;background:rgba(230,235,220,.15);margin:0 9px}.reset-button{margin-left:auto;border:0;background:transparent;color:#9aaba4;font-size:17px;cursor:pointer;padding:3px 6px;border-radius:5px;transition:color .2s,transform .3s}.reset-button:hover{color:#f2d79c;transform:rotate(-35deg)}footer{height:54px;border-top:1px solid rgba(226,237,222,.08);display:flex;justify-content:space-between;align-items:center;color:#728783;font-size:10px}footer .footer-star{color:#d8bc8d;margin-left:4px}.toast{position:fixed;z-index:4;bottom:24px;left:50%;transform:translate(-50%,12px);padding:11px 18px;border:1px solid rgba(236,215,164,.2);background:rgba(28,43,50,.96);border-radius:30px;color:#f1dfb8;font-size:12px;opacity:0;transition:.3s;pointer-events:none;box-shadow:0 8px 30px rgba(0,0,0,.25);white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.firefly{position:absolute;width:4px;height:4px;background:#f6d78e;border-radius:50%;box-shadow:0 0 12px 3px rgba(242,207,127,.56);animation:firefly 9s ease-in-out infinite}.full-glow .scene-glow{opacity:1;transform:scale(1.4)}.full-glow .lantern-wrap{filter:drop-shadow(0 8px 30px rgba(255,198,112,.38))}.low-glow .scene-glow{opacity:.22}.low-glow .lantern-wrap{filter:drop-shadow(0 8px 15px rgba(255,186,101,.05))}
@keyframes float{0%,100%{transform:translateY(-2px)}50%{transform:translateY(-8px)}}@keyframes flicker{0%,100%{transform:scale(.97,1);opacity:.9}50%{transform:scale(1.05,.94);opacity:1}72%{transform:scale(.98,1.04)}}@keyframes twinkle{from{opacity:.22}to{opacity:.62}}@keyframes sparkle{0%,100%{opacity:.2;transform:scale(.8)}50%{opacity:1;transform:scale(1.15)}}@keyframes shimmer{0%,45%{transform:translateX(-100%)}70%,100%{transform:translateX(120%)}}@keyframes firefly{0%,100%{transform:translate(0,0);opacity:.1}35%{transform:translate(22px,-18px);opacity:.9}68%{transform:translate(-13px,-36px);opacity:.4}}
